#!/usr/bin/env bash
# GATE M2 — deterministic reprojection.
#
# Proves ggen is a pure function of the admitted ontology graph O* (root
# ontology.ttl plus C-sorted canonical ontology/**/*.ttl fragments) and pack
# templates, with no dependency on what was already sitting on disk.
# Manufactured provenance is signalled per-FILE by the "GENERATED by ggen ...
# Do not edit." header comment (first non-shebang line), never by directory
# placement -- ggen output lives in the same src/, lib/, test/, gleam/,
# schema/, docs/reference/ directories hand-authored code uses. This script
# finds every manufactured file by that marker, deletes exactly those files,
# regenerates, and diffs.
set -euo pipefail
cd "$(dirname "$0")/.."

MARKER="GENERATED by ggen"
SEARCH_DIRS=(src lib test gleam/src gleam/test schema docs/reference)
# Deliberately NOT bare "gleam" -- gleam/src and gleam/test (now recursive,
# see find_manufactured below) already cover every real manufactured
# gleam file; a bare "gleam" entry would also recursively sweep
# gleam/build/ (255 real compiled artifacts as of 2026-08-30), which is
# never manufactured source and must never be deleted by this gate.
#
# gleam/gleam.toml (top-level, NOT under gleam/src or gleam/test) is a real
# additional gap in the same family: it IS manufactured (carries the
# "GENERATED by ggen" marker -- see beam4pm_process_model_pack's
# templates/gleam_toml.tmpl) but lives directly in gleam/, one directory
# SEARCH_DIRS never lists. Caught for real this session (Phase E, POWL 2.0
# wire records): the admitted bpm:RecordType graph grew again (POWL
# powl_freq/powl_leaf/powl_partial_order_edge/powl_choice_graph_edge added),
# gleam.toml's own manufactured record-count description changed, and
# find_manufactured's omission left it un-deleted, producing the exact same
# FM-WRITE-005 refusal class the gleam/src nesting fix above already
# describes. GLEAM_TOP_LEVEL_FILES below scans ONLY gleam/'s own top-level
# files (maxdepth 1) -- never gleam/build/, which sits one level deeper and
# must never be swept by this gate.
GLEAM_TOP_LEVEL_FILES() { find gleam -maxdepth 1 -type f 2>/dev/null; }

find_manufactured() {
  # Recursive (no -maxdepth): a real bug caught by this exact gate --
  # gleam/src/beam4pm/discovery.gleam and .../types.gleam live one level
  # NESTED under gleam/src/ (gleam's own package-name subdirectory
  # convention), so an earlier -maxdepth 1 scan of "gleam/src" silently
  # never found them, leaving them un-deleted-and-regenerated across every
  # prior GATE M2 cycle and producing real FM-WRITE-005 refusals the
  # moment their content genuinely needed to change (e.g. the admitted
  # bpm:RecordType graph growing from 31 to 35 record types). head -3:
  # marker is always within the first couple of lines (gleam.toml has no
  # comment syntax collision concern; its own header is a TOML comment).
  {
    for d in "${SEARCH_DIRS[@]}"; do
      [ -d "$d" ] || continue
      find "$d" -type f 2>/dev/null
    done
    GLEAM_TOP_LEVEL_FILES
  } | sort -u | while read -r f; do
    # -i: case-insensitive. Another real, disclosed gap this gate found:
    # docs/reference/beam4pm_types_reference.md's own manufactured header
    # reads "*Generated by ggen ..." (lowercase g) rather than the erl/ex/
    # gleam convention's "GENERATED by ggen" -- an exact-case match missed
    # this one real file for this gate's entire prior existence.
    head -3 "$f" 2>/dev/null | grep -qi "$MARKER" && echo "$f"
  done
}

echo "== pass 1: locating manufactured files by header marker =="
mapfile -t before_files < <(find_manufactured)
echo "found ${#before_files[@]} manufactured files"

echo "== pass 2: sha256 before deletion =="
before_sums="$(for f in "${before_files[@]}"; do shasum -a 256 "$f"; done | sort)"

# Hand-authored tests that reference manufactured modules at compile time are
# temporarily removed during the regeneration window so intermediate ggen
# and ggen_igniter verification cannot observe a deliberately incomplete
# projection set.
STASH_DIR="$(mktemp -d)"
ONTOLOGY_BACKUP="$(mktemp)"
cp ontology.ttl "$ONTOLOGY_BACKUP"
HAND_AUTHORED_DEPENDENT_TESTS=(test/beam4pm_actuation_k8s_test.exs test/beam4pm_process_governor_k8s_test.exs)
restore_stash() {
  # `if ... ; then mv; fi` (not a bare `[ -f ] && mv`) -- a bare `test && cmd`
  # statement is falsy whenever the test is false, and under this script's
  # `set -e` (still armed inside an EXIT trap, per Bash's documented
  # errexit-in-trap behavior) a single falsy iteration here aborts the
  # WHOLE trap immediately, skipping every later loop iteration and the
  # final rmdir. Caught for real this session: a mid-pass-3 failure (a
  # different, since-fixed find_manufactured gap) left both
  # HAND_AUTHORED_DEPENDENT_TESTS files stranded in an orphaned STASH_DIR
  # instead of restored to test/ -- recovered via `git checkout --` only
  # because both are hand-authored and already committed; this fix removes
  # the underlying early-abort risk so a future failure here can never
  # strand a file the same way again.
  for f in "${HAND_AUTHORED_DEPENDENT_TESTS[@]}"; do
    stashed="$STASH_DIR/$(basename "$f")"
    if [ -f "$stashed" ]; then
      mv "$stashed" "$f"
    fi
  done
  rmdir "$STASH_DIR" 2>/dev/null || true
}
restore_ontology() {
  if [ -f "$ONTOLOGY_BACKUP" ]; then
    cp "$ONTOLOGY_BACKUP" ontology.ttl
    rm -f "$ONTOLOGY_BACKUP"
  fi
}

# BACKUP_DIR holds a real copy of every manufactured file (before_files),
# PLUS ggen.lock (deleted unconditionally by pass 3 below but not itself
# marker-tagged, so it is not part of before_files), taken BEFORE deletion
# -- so a delete-then-regenerate that fails partway through (either engine)
# can be rolled back to a byte-identical working tree instead of leaving
# files deleted-and-never-regenerated. This is the real root-cause fix for
# the GATE M2 destructive-deletion defect: the ggen_igniter leg
# (scripts/igniter_sync.sh) writes lib/beam4pm_ash.ex via
# `mix ggen_igniter.sync --out lib/beam4pm_ash.ex`, then immediately runs
# `mix compile --warnings-as-errors` / `mix test` as its OWN internal
# verification step. If `mix ggen_igniter.sync` itself fails (oxigraph
# Rustler NIF build failure, a bad ontology/query/template combination, a
# transient toolchain/docker issue on the primary ggen leg) the affected
# file is never (re)written -- but pass 3 above had already deleted the
# pre-existing copy. Under `set -e` that failure propagates straight to
# this script's exit with 320+ manufactured files (lib/beam4pm_ash.ex among
# them) missing from the working tree and no automatic recovery.
# BACKUP_DIR + restore_manufactured below close that gap: ANY non-zero exit
# restores every before_files entry (and ggen.lock) from BACKUP_DIR,
# verified by `git status --short` being identical before/after a FAILING
# run, not just a successful one.
BACKUP_DIR="$(mktemp -d)"
for f in "${before_files[@]}"; do
  mkdir -p "$BACKUP_DIR/$(dirname "$f")"
  cp -p "$f" "$BACKUP_DIR/$f"
done
[ -f ggen.lock ] && cp -p ggen.lock "$BACKUP_DIR/ggen.lock"

restore_manufactured() {
  # Only fires on a non-zero exit (see the trap below) -- a successful run
  # regenerates every before_files entry for real via the sync scripts and
  # pass 4 proves byte-identity, so restoring from backup on success would
  # just silently discard the sync scripts' real regenerated output.
  echo "GATE M2: regenerate step failed -- restoring ${#before_files[@]} manufactured files (+ggen.lock) from pre-delete backup" >&2
  for f in "${before_files[@]}"; do
    mkdir -p "$(dirname "$f")"
    cp -p "$BACKUP_DIR/$f" "$f"
  done
  [ -f "$BACKUP_DIR/ggen.lock" ] && cp -p "$BACKUP_DIR/ggen.lock" ggen.lock
}

on_exit() {
  status=$?
  if [ "$status" -ne 0 ]; then
    restore_manufactured
  fi
  restore_stash
  restore_ontology
  rm -rf "$BACKUP_DIR"
  exit "$status"
}
# Restore on ANY exit, not just the happy path -- an earlier round of
# debugging this exact script left manufactured files deleted-and-never-
# regenerated when a sync script aborted mid-sequence; a bare stash without
# this trap would reproduce the same class of self-inflicted damage here.
# Restores BOTH hand-authored tests and the canonical root ontology on
# every exit (not just failure), since restore_ontology must undo the
# pass 2b composition below regardless of pass 3's outcome.
trap on_exit EXIT
for f in "${HAND_AUTHORED_DEPENDENT_TESTS[@]}"; do
  if [ -f "$f" ]; then
    mv "$f" "$STASH_DIR/$(basename "$f")"
  fi
done

echo "== pass 2b: compose canonical ontology fragments into admitted O* =="
mapfile -t ONTOLOGY_FRAGMENTS < <(find ontology -type f -name '*.ttl' -print 2>/dev/null | LC_ALL=C sort)
for fragment in "${ONTOLOGY_FRAGMENTS[@]}"; do
  echo "compose: $fragment"
  printf '\n\n# ---- composed canonical fragment: %s ----\n' "$fragment" >> ontology.ttl
  cat "$fragment" >> ontology.ttl
done

echo "== pass 3: delete manufactured files, regenerate (both engines) =="
for f in "${before_files[@]}"; do rm -f "$f"; done
rm -f ggen.lock
ggen sync run
# lib/beam4pm_ash.ex, lib/beam4pm_actuation.ex, lib/beam4pm_process_governor.ex,
# lib/beam4pm_receipt_chain.ex, and their tests are manufactured by the
# SECOND engine (ggen_igniter, mix ggen_igniter.sync), not by the Rust ggen
# binary. receipt_chain_sync.sh renders beam4pm_receipt_chain.ex first, then
# re-runs the dependent actuation/governor families in dependency order.
# OCEL v2 network ingestion router (lib/beam4pm_ocel_ingest.ex + its test),
# manufactured by the ggen_igniter engine from the admitted
# bpmi:AdmittedIngestRoute graph. Must run BEFORE igniter_sync.sh: that
# script's own internal `mix test` boots BeamPM.Application, which starts a
# real Bandit listener on this router module -- if the router hasn't been
# regenerated yet (deleted in pass 3, not yet rewritten), the app fails to
# boot and the whole gate run aborts.
bash scripts/ocel_ingest_sync.sh

# receipt_chain_sync.sh renders beam4pm_receipt_chain.ex, which is fully
# static (no ontology/graph bindings, no dependency on igniter's Ash
# resources -- see the script's own header comment). Must also run BEFORE
# igniter_sync.sh: the hand-written lib/beam4pm_contracts.ex (BeamPM.Contracts
# .manifest/0) calls BeamPM.ReceiptChain.hash_file!/1 at runtime, and
# igniter_sync.sh's own internal `mix test` exercises test/
# beam4pm_contracts_test.exs -- if beam4pm_receipt_chain.ex hasn't been
# regenerated yet (deleted in pass 3), that test suite fails with
# "function BeamPM.ReceiptChain.hash_file!/1 is undefined". Real ordering bug
# GATE M2 caught for real once beam4pm_contracts.ex started depending on
# ReceiptChain across the module boundary.
bash scripts/receipt_chain_sync.sh

bash scripts/igniter_sync.sh

# RF1/RF2/RF3 function-surface Reactor validation families are independent.
source scripts/env/rust4pm_reactor_env.sh
bash scripts/rf1_dfg_sync.sh
bash scripts/rf2_conformance_sync.sh
bash scripts/rf3_ocel_sync.sh

# Revenue suite + Claude-workflow-Reactor families.
bash scripts/revenue_economics_sync.sh
bash scripts/revenue_metering_sync.sh
bash scripts/claude_workflow_reactor_sync.sh

# beam4pm_pro P0 gap-closure capabilities.
bash scripts/pro_capability_manifest_sync.sh
bash scripts/pro_compatibility_sync.sh
bash scripts/pro_license_sync.sh
bash scripts/pro_doctor_sync.sh
bash scripts/pro_tenancy_sync.sh
bash scripts/pro_ocpm_discovery_sync.sh
bash scripts/pro_simulation_sync.sh

# Transplants from ex4pm/xaas: per-record-type doc fan-out.
bash scripts/pro_type_pages_sync.sh

# The composed ontology exists only in the regeneration workspace; canonical
# fragments stay checked in as authority. Restore the root before hashing the
# repository consequences so composition itself can never leak into a diff.
restore_ontology
restore_stash
# Every sync script above completed with exit 0 -- the working tree now
# holds real regenerated output, not a partial delete. Disarm the failure
# trap (from this point on, a pass-4 hash mismatch is a real determinism
# bug to report, never a destructive-deletion event to roll back) and drop
# the now-unneeded pre-delete backup.
trap - EXIT
rm -rf "$BACKUP_DIR"

echo "== pass 4: sha256 after regeneration =="
mapfile -t after_files < <(find_manufactured)
after_sums="$(for f in "${after_files[@]}"; do shasum -a 256 "$f"; done | sort)"

if [ "$before_sums" != "$after_sums" ]; then
  echo "GATE M2: FAIL -- regenerated output differs from the deleted originals" >&2
  diff <(echo "$before_sums") <(echo "$after_sums") >&2 || true
  exit 1
fi

echo "GATE M2: PASS -- ${#after_files[@]} manufactured files byte-identical across delete+regenerate"